    public static func loadStaticProducts() -> [String: ProviderProductSpec] {
        guard let data = rawProductsJSON.data(using: .utf8),
              let dict = try? JSONDecoder().decode([String: ProviderProductSpec].self, from: data) else {
            return [:]
        }
        return dict
    }

    public static func loadStaticBindings() -> [ProviderProtocolBindingSpec] {
        guard let data = rawBindingsJSON.data(using: .utf8),
              let list = try? JSONDecoder().decode([ProviderProtocolBindingSpec].self, from: data) else {
            return []
        }
        return list
    }
